#!/bin/bash
exec /usr/bin/python3 - "{query}" <<'PYEOF'
# -*- coding: utf-8 -*-
import json
import os
import re
import sqlite3
import subprocess
import sys

query = sys.argv[1] if len(sys.argv) > 1 else ""

def env(name, default):
    v = os.environ.get(name, "")
    return v if v else default

# Configuration
default_minutes = env("DEFAULT_MINUTES", "10")
default_rule = env("DEFAULT_RULE_NAME", "Default")
prefix = env("MODE_PREFIX", "[Mode]")
auto_revert = env("AUTO_REVERT", "true").lower() in ("true", "1", "yes")

home = os.path.expanduser("~")
default_db = os.path.join(
    home,
    "Library/Group Containers/4QE86VV38D.app.loshadki.OpenIn/"
    "Library/Application Support/OpenIn/local.sqlite",
)
db_path = env("OPENIN_DB_PATH", default_db)

fallback_icon = env("FALLBACK_BROWSER_APP_PATH", "/Applications/Safari.app")
if not os.path.isdir(fallback_icon):
    fallback_icon = "/System/Applications/Safari.app"

# Resolve OpenIn.app icon
openin_icon = None
for cand in (
    "/Applications/OpenIn.app",
    "/Applications/Setapp/OpenIn.app",
    "/Applications/setapp/OpenIn.app",
):
    if os.path.isdir(cand):
        openin_icon = cand
        break
if openin_icon is None:
    openin_icon = fallback_icon

def emit_error(msg):
    print(json.dumps({
        "items": [{
            "title": "エラー",
            "subtitle": msg,
            "valid": False,
            "icon": {"path": "icon.png"},
        }]
    }, ensure_ascii=False))
    sys.exit(0)

# Extract minutes from query (first integer found)
m = re.search(r"\d+", query or "")
minutes = m.group(0) if m else default_minutes

if not os.path.isfile(db_path):
    emit_error(f"OpenInのDBが見つかりません: {db_path}")

# Read all rules + their primary (lowest ZAPPORDER) app + ZDISABLED flag
try:
    conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    cur = conn.cursor()
    cur.execute("""
        SELECT
          r.ZNAME,
          r.ZDISABLED,
          COALESCE((
            SELECT a.ZPATH FROM Z_6USEDINRULES j
            JOIN ZOPENINHANDLERAPP a ON a.Z_PK = j.Z_6SELECTEDAPPS
            WHERE j.Z_7USEDINRULES = r.Z_PK
            ORDER BY a.ZAPPORDER ASC LIMIT 1
          ), ''),
          COALESCE((
            SELECT a.ZBUNDLEIDENTIFIER FROM Z_6USEDINRULES j
            JOIN ZOPENINHANDLERAPP a ON a.Z_PK = j.Z_6SELECTEDAPPS
            WHERE j.Z_7USEDINRULES = r.Z_PK
            ORDER BY a.ZAPPORDER ASC LIMIT 1
          ), '')
        FROM ZOPENINHANDLERRULE r
        WHERE r.ZNAME IS NOT NULL
        ORDER BY r.ZNAME
    """)
    rows = cur.fetchall()
    conn.close()
except sqlite3.Error as e:
    emit_error(f"DBの読み取りに失敗しました: {e}")

if not rows:
    emit_error("OpenInにルールが登録されていません。先にOpenIn側でルールを作成してください。")

# Cache mdfind results across rules
icon_cache = {}

def resolve_icon(app_path, bundle_id):
    if app_path and os.path.isdir(app_path):
        return app_path
    if bundle_id:
        if bundle_id in icon_cache:
            return icon_cache[bundle_id]
        try:
            out = subprocess.run(
                ["mdfind", f'kMDItemCFBundleIdentifier == "{bundle_id}"'],
                capture_output=True, text=True, timeout=2,
            )
            for line in out.stdout.splitlines():
                line = line.strip()
                if line and os.path.isdir(line):
                    icon_cache[bundle_id] = line
                    return line
        except (subprocess.TimeoutExpired, OSError):
            pass
    return fallback_icon

# First pass: figure out which rule is currently active
# (only one rule should be enabled at a time, but be defensive)
active_rule_name = None
default_rule_active = False
for rule_name, disabled, _, _ in rows:
    if disabled == 0:
        if rule_name == default_rule:
            default_rule_active = True
        elif rule_name and rule_name.startswith(prefix):
            active_rule_name = rule_name

ACTIVE_MARK = "▶"

items = []
for rule_name, disabled, app_path, bundle_id in rows:
    if not rule_name:
        continue
    if not rule_name.startswith(prefix):
        continue
    display = rule_name[len(prefix):]
    if display.startswith(" "):
        display = display[1:]
    if not display:
        continue

    icon_path = resolve_icon(app_path, bundle_id)

    is_active = (rule_name == active_rule_name)

    if is_active:
        if auto_revert:
            subtitle = f"{ACTIVE_MARK} 現在有効（{minutes}分後に自動復帰）"
        else:
            subtitle = f"{ACTIVE_MARK} 現在有効"
    else:
        if auto_revert:
            subtitle = f"「{display}」に切り替え（{minutes}分後に自動復帰）"
        else:
            subtitle = f"「{display}」に切り替え（自動復帰なし）"

    items.append({
        "uid": display,
        "title": display,
        "subtitle": subtitle,
        "arg": f"{rule_name}|{minutes}",
        "icon": {"type": "fileicon", "path": icon_path},
    })

if not items:
    emit_error(f"接頭辞「{prefix}」が付いたルールが見つかりません。OpenIn側でルール名の先頭にこの接頭辞を付けてください。")

# Append default item
if default_rule_active:
    default_subtitle = f"{ACTIVE_MARK} 現在有効"
else:
    default_subtitle = f"今すぐ「{default_rule}」に戻す"

items.append({
    "uid": "__default__",
    "title": default_rule,
    "subtitle": default_subtitle,
    "arg": "__DEFAULT__|0",
    "icon": {"type": "fileicon", "path": openin_icon},
})

print(json.dumps({"items": items}, ensure_ascii=False))
PYEOF
